// parser.h
//
// This file is responsible for syntax analysis.
// The parser processes the tokens generated by the lexer and
// checks whether they follow the grammar rules of the language.
// It constructs an Abstract Syntax Tree (AST) representing
// the structure of the source code.

#include <string>
#include <memory>

#include "ast.h"
#include "error.h"

struct Program {
    std::vector<std::unique_ptr<Statement>> statements;
};

class Parser {
private:
    ErrorHandler& errorHandler;
    Lexer lexer;
    Token currentToken;
public:
    Parser(std::string_view source, ErrorHandler& errorHandler) : errorHandler(errorHandler), lexer(source, errorHandler) {
        currentToken = lexer.nextToken();
    }
    
    // Parse the program and return the root of the AST
    std::unique_ptr<Program> parseProgram() {
        auto program = std::make_unique<Program>();

        while (currentToken.type != TokenType::END_OF_FILE) {

            auto statement = parseStatement();

            if (!statement) {
                return nullptr;
            }

            program->statements.push_back(std::move(statement));
        }

        return program;
    }

    std::unique_ptr<Statement> parseStatement() {

        if (currentToken.type == TokenType::LET) 
            return parseDeclarationStatement();
        else if (currentToken.type == TokenType::PRINT) 
            return parsePrintStatement();
        else if (currentToken.type == TokenType::IDENTIFIER) 
            return parseExpressionStatement();

        return nullptr;
    }
private:

    bool expect(TokenType expected) {
        if (currentToken.type != expected) {
            return false;
        }
        currentToken = lexer.nextToken();
        return true;
    }

    std::unique_ptr<VariableDeclaration> parseDeclarationStatement() {
        if (!expect(TokenType::LET)) return nullptr;

        if (currentToken.type != TokenType::IDENTIFIER)
            return nullptr;

        std::string name(currentToken.value);

        if (!expect(TokenType::IDENTIFIER)) return nullptr;
        if (!expect(TokenType::EQUAL)) return nullptr;

        auto expression = parseExpression();
        if (!expression) return nullptr;

        if (!expect(TokenType::SEMICOLON)) return nullptr;

        return std::make_unique<VariableDeclaration>(std::move(name), std::move(expression));    
    }

    std::unique_ptr<PrintStatement> parsePrintStatement() {
        if (!expect(TokenType::PRINT)) return nullptr;
        if (!expect(TokenType::LEFT_PAREN)) return nullptr;

        auto expression = parseExpression();
        if (!expression) return nullptr;

        if (!expect(TokenType::RIGHT_PAREN)) return nullptr;
        if (!expect(TokenType::SEMICOLON)) return nullptr;

        return std::make_unique<PrintStatement>(std::move(expression));
    }

    std::unique_ptr<Statement> parseExpressionStatement() {
        auto expression = parseExpression();

        if (!expression) return nullptr;
        if (!expect(TokenType::SEMICOLON)) return nullptr;

        return std::make_unique<ExpressionStatement>(std::move(expression));
    }

    // Parse a single value, such as a number, variable, or parenthesized expression
    std::unique_ptr<Expression> parseExpressionPrimary() {
        if (currentToken.type == TokenType::IDENTIFIER) {
            std::string name(currentToken.value);

            currentToken = lexer.nextToken();

            return std::make_unique<IdentifierExpression>(name);
        }

        if (currentToken.type == TokenType::NUMBER) {
            int value = std::stoi(std::string(currentToken.value));

            currentToken = lexer.nextToken();

            return std::make_unique<NumberExpression>(value);
        }

        if (currentToken.type == TokenType::LEFT_PAREN) {
            currentToken = lexer.nextToken();

            auto expression = parseExpression();
            if (!expression) return nullptr;

            if (!expect(TokenType::RIGHT_PAREN)) return nullptr;

            return expression;
        }

        return nullptr;
    }

    // Parse multiplication and division expressions
    std::unique_ptr<Expression> parseTerm() {
        auto left = parseExpressionPrimary();
        if (!left) return nullptr;

        while (currentToken.type == TokenType::STAR || currentToken.type == TokenType::SLASH) {
            char op;
            switch (currentToken.type) {
                case TokenType::STAR:
                    op = '*';
                    break;

                case TokenType::SLASH:
                    op = '/';
                    break;

                default:
                    return nullptr;
            }

            currentToken = lexer.nextToken();

            auto right = parseExpressionPrimary();
            if (!right) return nullptr;

            left = std::make_unique<BinaryExpression>(std::move(left), op, std::move(right));
        }

        return left;
    }

    // Parse addition and subtraction expressions
    std::unique_ptr<Expression> parseExpression() {
        auto left = parseTerm();
        if (!left) return nullptr;

        while (currentToken.type == TokenType::PLUS  || currentToken.type == TokenType::MINUS) {
            char op;

            switch (currentToken.type) {
                case TokenType::PLUS:
                    op = '+';
                    break;

                case TokenType::MINUS:
                    op = '-';
                    break;

                default:
                    return nullptr;
            }

            currentToken = lexer.nextToken();

            auto right = parseTerm();
            if (!right) return nullptr;

            left = std::make_unique<BinaryExpression>(std::move(left), op, std::move(right));
        }

        return left;
    }  

};